def rotar(lista, k):
    if not lista:
        return []

    n = len(lista)
    k %= n

    if k == 0:
        return lista[:]

    return lista[-k:] + lista[:-k]

def anagramas(a, b):
    a = a.replace(" ", "").lower()
    b = b.replace(" ", "").lower()
    return sorted(a) == sorted(b)

def balanceado(s: str) -> bool:
    pila = []
    cierre = {')': '(', ']': '[', '}': '{'}

    for caracter in s:
        if caracter in '([{':
            pila.append(caracter)
        elif caracter in cierre:
            if not pila or pila[-1] != cierre[caracter]:
                return False
            pila.pop()

    return not pila
